def cc(n):
    s = ''
    while n != 0:
        s = str(n % 3 ) +  s
        n //= 3
    return s

def f(n):
    s = cc(n)
    sum_digits = s.count('1') + s.count('2') * 2
    if sum_digits % 3 == 0:
        s = s.replace('1','*').replace('0','1').replace('*','0')
        s = '10' + s
    else:
        s += '101'
        s = '22' + s[2:]
    return int(s,3)

